1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"strings"
9	
10		"github.com/entireio/entire-brain/internal/apiurl"
11		"github.com/entireio/entire-brain/internal/cli/internal/base"
12		"github.com/entireio/entire-brain/internal/providerdetail"
13		"github.com/spf13/cobra"
14		"golang.org/x/mod/semver"
15	)
16	
17	// minHostCLIVersion is the first host CLI release that ships `entire repo view
18	// --json` (entireio/cli#2758), which placement resolution depends on. Only
19	// connect's placement shell-out checks it: local-only brain use and explicit
20	// --repo-id/--api-url never touch the host CLI version. Empty disables the
21	// gate explicitly. A var so tests can exercise the gate.
22	var minHostCLIVersion = "0.11.6"
23	
24	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
25	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
26	// and its cell API base URL, both top-level fields.
27	type hostedPlacement struct {
28		RepoID string `json:"repoId"`
29		APIURL string `json:"apiUrl"`
30	}
31	
32	type connectOptions struct {
33		repoID string
34		apiURL string
35	}
36	
37	func newConnectCommand(opts Options) *cobra.Command {
38		var connectOpts connectOptions
39		cmd := &cobra.Command{
40			Use:   "connect",
41			Short: "Bind this repository to its hosted brain explicitly",
42			Long: `connect binds this repository to its hosted brain: it records the repo id and
43	API base URL (non-secrets only — the host CLI's own login mints a fresh token
44	per sync), then runs one immediate sync so the first pull happens right away.
45	
46	Running connect (or the onboarding flow) is the ONLY way a repository starts
47	syncing: by default memories stay local and background triggers never connect
48	a repo on their own. Placement resolves through the host CLI (entire repo
49	view); pass --repo-id and --api-url to bypass resolution — a non-default cell
50	or a staging target. Re-running connect re-joins after 'entire brain
51	disconnect'.`,
52			Args: cobra.NoArgs,
53			RunE: func(cmd *cobra.Command, args []string) error {
54				return runConnect(cmd, opts, connectOpts)
55			},
56		}
57		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
58		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
59		return cmd
60	}
61	
62	func runConnect(cmd *cobra.Command, opts Options, connectOpts connectOptions) error {
63		ctx := cmd.Context()
64		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
65		if err != nil {
66			return err
67		}
68		if !local {
69			return fmt.Errorf("connect requires a local repository path")
70		}
71		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
72		if err != nil {
73			return err
74		}
75	
76		repoID := strings.TrimSpace(connectOpts.repoID)
77		apiURL := strings.TrimSpace(connectOpts.apiURL)
78		if repoID == "" || apiURL == "" {
79			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
80			if placementErr != nil {
81				// An already-connected (or disconnected — the opt-out keeps its
82				// coordinates) repo stays re-connectable without flags: re-connect
83				// means re-sync, not re-resolve.
84				if existing, present, readErr := readHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
85					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
86				} else {
87					// The hint sits on its own line: the host CLI's message ends
88					// with a newline of its own, so a "; pass ..." suffix used to
89					// dangle on a line starting with ";".
90					return fmt.Errorf("connect: %w\nOr pass --repo-id and --api-url explicitly", placementErr)
91				}
92			}
93			if repoID == "" {
94				repoID = resolved.RepoID
95			}
96			if apiURL == "" {
97				apiURL = resolved.APIURL
98			}
99		}
100		// Whether this run re-affirms an existing connection decides the success
101		// headline: "connected" must not read like a state change when nothing
102		// changed.
103		existing, existingPresent, existingErr := readHostedRepoBinding(storage.BrainDir)
104		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
105		if err != nil {
106			return fmt.Errorf("connect: %w", err)
107		}
108		already := existingErr == nil && existingPresent && !existing.OptedOut &&
109			existing.RepoID == binding.RepoID && existing.BaseURL == binding.BaseURL
110		// A connected repo wants the push-beat upload: install our pre-push hook
111		// (chained beside whatever hook owns the slot). Best-effort — a hook
112		// problem must not fail the connect.
113		if hookState, hookPath, hookErr := installPushHook(ctx, opts, repoDir); hookErr != nil {
114			fmt.Fprintf(cmd.ErrOrStderr(), "connect: push hook not installed (uploads ride the daemon tick): %v\n", hookErr)
115		} else if hookState == pushHookSharedDir {
116			fmt.Fprintf(cmd.ErrOrStderr(), "connect: core.hooksPath (%s) is shared across repos; push hook not managed — uploads ride the daemon tick\n", hookPath)
117		}
118		// The kill switch suppresses every sync this command is about to promise,
119		// so say that instead of "now syncing". The binding still gets recorded:
120		// the environment only subtracts, and unsetting it resumes syncing.
121		if brainNoEgressMode() {
122			renderHostedBanner(cmd.OutOrStdout(),
123				"Connected: repo "+binding.RepoID+" — but nothing syncs while "+noEgressToggleName()+" is set",
124				"The binding is recorded and memories stay local. Unset "+noEgressToggleName()+" to start syncing.")
125			return nil
126		}
127		// Connect doubles as the initial pull so a fresh clone receives team
128		// memories immediately. The sync runs BEFORE the banner so the headline
129		// reports what actually happened: a connect whose first pull failed has
130		// not started syncing, and claiming so hides a dead connection.
131		outcome, err := hostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, hostedSyncBranch(ctx, opts.Runner, repoDir))
132		if err != nil {
133			return err
134		}
135		if !outcome.PullSucceeded {
136			verdict := "failed"
137			if !outcome.Attempted {
138				verdict = "did not run"
139			}
140			return fmt.Errorf("connect: repo %s is bound, but the first sync %s (details above); memories stay local until a sync succeeds — fix the cause and re-run '%s'",
141				binding.RepoID, verdict, brainInvocation(os.LookupEnv, "connect"))
142		}
143		headline := "Connected: repo " + binding.RepoID + " is now syncing memories"
144		if already {
145			headline = "Already connected: repo " + binding.RepoID + " — memories are syncing"
146		}
147		renderHostedBanner(cmd.OutOrStdout(), headline,
148			"Memories sync periodically, at session end, and on git push. Teammates' memories merge into this repo's local brain.")
149		return nil
150	}
151	
152	// normalizeHostedBinding validates the target and strips a quoted /api/v1
153	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
154	// docs examples), but the factsync client appends /api/v1/repos/... itself —
155	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
156	// is an opt-in.
157	func normalizeHostedBinding(repoID, apiURL string) (hostedRepoBinding, error) {
158		if strings.TrimSpace(repoID) == "" {
159			return hostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
160		}
161		validated, err := apiurl.Validate(apiURL)
162		if err != nil {
163			return hostedRepoBinding{}, err
164		}
165		return hostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
166	}
167	
168	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
169	// there, including an opt-out — running connect is how the user opts back in.
170	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
171		binding, err := normalizeHostedBinding(repoID, apiURL)
172		if err != nil {
173			return hostedRepoBinding{}, err
174		}
175		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
176			return hostedRepoBinding{}, err
177		}
178		return binding, nil
179	}
180	
181	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
182	// placement.
183	func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
184		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
185		defer cancel()
186		if err := checkHostCLIVersion(ctx, runner, repoDir, minHostCLIVersion); err != nil {
187			return hostedPlacement{}, err
188		}
189		stdout, stderr, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "view", "--json")
190		if err != nil {
191			return hostedPlacement{}, placementFailureError(err, stderr)
192		}
193		var result hostedPlacement
194		if err := decodeHostCLIJSON(stdout, &result); err != nil {
195			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
196		}
197		return result, nil
198	}
199	
200	// placementFailureError reduces a failed `entire repo view --json` to the line
201	// the host CLI actually said. The runner's wrap carries debug framing — an
202	// argv echo plus the host's "Using context '…'." login banner — that a human
203	// reading connect's failure never needs. Drop the banner, then let
204	// providerdetail.Summary keep the host's Error:-marked or first stderr line.
205	func placementFailureError(runErr error, stderr []byte) error {
206		var kept []string
